import java.io.*;import java.util.*;public class Solution{public static void main(String[] args) throws Exception{BufferedReader br=new BufferedReader(new InputStreamReader(System.in));int q=Integer.parseInt(br.readLine().trim());Deque<Integer> stackEnq=new ArrayDeque<>();Deque<Integer> stackDeq=new ArrayDeque<>();StringBuilder sb=new StringBuilder();for(int i=0;i<q;i++){String line=br.readLine();if(line==null||line.isEmpty()){i--;continue;}StringTokenizer st=new StringTokenizer(line);int type=Integer.parseInt(st.nextToken());if(type==1){int x=Integer.parseInt(st.nextToken());stackEnq.push(x);}else if(type==2){if(stackDeq.isEmpty()){while(!stackEnq.isEmpty()){stackDeq.push(stackEnq.pop());}}if(!stackDeq.isEmpty()){stackDeq.pop();}}else if(type==3){if(stackDeq.isEmpty()){while(!stackEnq.isEmpty()){stackDeq.push(stackEnq.pop());}}if(!stackDeq.isEmpty()){sb.append(stackDeq.peek()).append('\n');}}}System.out.print(sb.toString());}}